                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.companyId,
                                    referencedTable: $$StoresTableReferences
                                        ._companyIdTable(db),
                                    referencedColumn: $$StoresTableReferences
                                        ._companyIdTable(db)
                                        .id,
                                  )
                                  as T;
