                      if (registersRefs)
                        await $_getPrefetchedData<
                          Store,
                          $StoresTable,
                          Register
                        >(
                          currentTable: table,
                          referencedTable: $$StoresTableReferences
                              ._registersRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$StoresTableReferences(
                                db,
                                table,
                                p0,
                              ).registersRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.storeId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (stockLocationsRefs)
                        await $_getPrefetchedData<
                          Store,
                          $StoresTable,
                          StockLocation
                        >(
                          currentTable: table,
                          referencedTable: $$StoresTableReferences
